</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

#define mp make_pair
#define pb push_back
#define fi first
#define se second
#define rep(i,a,b) for (int i=(a),_ed=(b);i<_ed;i++)
#define per(i,a,b) for (int i=(b)-1,_ed=(a);i>=_ed;i--)
#define all(x) (x).begin(),(x).end()
#define sz(x) ((int)(x).size())
#define cl(x) memset((x),0,sizeof(x))
#define lld "%lld"

typedef long long ll;
typedef pair<int,int> pii;
typedef vector<int> vi;

const int MM_N = 33;
const int mo = 1e9+7;

int mm_n;
struct mat{
    int a[MM_N][MM_N];
    void plus(){
        rep(i,0,mm_n)rep(j,0,mm_n)a[i][j]=(a[i][j]%mo+mo)%mo;
    }
}one;

mat operator*(const mat&a,const mat&b){
    static ll ans[MM_N][MM_N];
    cl(ans);
    ll infa=8e18;
    rep(k,0,mm_n)rep(i,0,mm_n)rep(j,0,mm_n){
        if((ans[i][j]+=1ll*a.a[i][k]*b.a[k][j])>=infa)ans[i][j]%=mo;
    }
    mat c;
    rep(i,0,mm_n)rep(j,0,mm_n)c.a[i][j]=ans[i][j]%mo;
    return c;
}

mat qpow(mat a,ll b){
    a.plus();
    mat n=one;
    do{
        if(b&1)n=n*a;
        a=a*a;
    }while(b>>=1);
    return n;
}

void mm_init(int sz){
    mm_n=sz;
    rep(i,0,mm_n)one.a[i][i]=1;
}

inline void gn(long long&x){
    int sg=1;char c;
    while(((c=getchar())<'0'||c>'9')&&c!='-');
    c=='-'?(sg=-1,x=0):(x=c-'0');
    while((c=getchar())>='0'&&c<='9')x=x*10+c-'0';
    x*=sg;
}

inline void gn(int&x){long long t;gn(t);x=t;}

int nu[111],tot;
mat a[100];

mat jia(const mat&x,int d){
    mat ret;
    rep(i,0,mm_n)rep(j,0,mm_n)ret.a[i!=mm_n-1?(i+d)%(mm_n-1):mm_n-1][j!=mm_n-1?(j+d)%(mm_n-1):mm_n-1]=x.a[i][j];
    return ret;
}

int main(){
    ll n;
    int k;
    gn(n);gn(k);
    mm_init(k+1);

    tot=0;
    while(n){
        nu[tot++]=n%k;
        n/=k;
    }

    rep(j,0,k+1)a[0].a[0][j]=1;
    rep(j,0,k+1)a[0].a[j][j]=1;

    rep(i,1,tot){
        mat now=one;
        rep(j,0,k)now=now*jia(a[i-1],j);
        a[i]=now;
    }

    int ad=0;
    mat ans=one;
    per(i,0,tot){
        rep(j,0,nu[i])
            ans=ans*jia(a[i],(j+ad)%k);
        ad=(ad+nu[i])%k;
    }

    int ret=0;
    rep(i,0,k+1)ret=(ret+ans.a[i][k])%mo;
    printf("%d\n",ret);
    return 0;
}
